import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { FiMessageSquare, FiUsers } from 'react-icons/fi';
import api from '../services/api';
import { useAuth } from '../context/AuthContext';

const ChatList = () => {
  const { user } = useAuth();
  const [chats, setChats] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const currentUserId = user ? String(user.id) : null;

  useEffect(() => {
    const fetchChats = async () => {
      try {
        const res = await api.get('/chats');
        setChats(res.data);
        setError(null);
      } catch (err) {
        setError('Erreur lors du chargement des conversations');
        console.error('Error fetching chats:', err);
      } finally {
        setLoading(false);
      }
    };

    fetchChats();
  }, []);

  const getParticipants = (chat) => chat.Users || chat.participants || [];

  const getRecipientName = (chat) => {
    if (chat.isGroup) return chat.name;
    const recipient = getParticipants(chat).find(p => String(p.id) !== currentUserId);
    if (recipient?.fullName) return recipient.fullName;
    const otherMessage = chat.Messages?.find(msg => String(msg.senderId) !== currentUserId);
    return otherMessage?.User?.fullName || chat.name || 'Conversation privée';
  };

  const getAvatarColor = (name) => {
    const colors = ['#3b82f6', '#ef4444', '#10b981', '#f59e0b', '#8b5cf6', '#ec4899'];
    const index = name.charCodeAt(0) % colors.length;
    return colors[index];
  };

  const getLastMessage = (chat) => {
    if (!chat.Messages || chat.Messages.length === 0) return 'Aucun message';
    return chat.Messages[0].content;
  };

  const getLastMessageTime = (chat) => {
    if (!chat.Messages || chat.Messages.length === 0) return '';
    const date = new Date(chat.Messages[0].createdAt);
    const today = new Date();
    if (date.toDateString() === today.toDateString()) {
      return date.toLocaleTimeString('fr-FR', { hour: '2-digit', minute: '2-digit' });
    }
    return date.toLocaleDateString('fr-FR', { month: 'short', day: 'numeric' });
  };

  if (loading) {
    return (
      <div className="container mx-auto p-6">
        <div className="animate-pulse">
          <div className="h-8 bg-gray-200 rounded w-1/3 mb-6"></div>
          <div className="space-y-3">
            {[1, 2, 3].map((i) => (
              <div key={i} className="h-16 bg-gray-200 rounded"></div>
            ))}
          </div>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="container mx-auto p-6">
        <div className="bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded">
          {error}
        </div>
      </div>
    );
  }

  return (
    <div className="container mx-auto p-6">
      <div className="mb-6 rounded-3xl bg-white shadow-lg border border-slate-200 px-6 py-5">
        <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3">
          <div>
            <h1 className="text-3xl font-bold text-slate-900 flex items-center gap-3">
              <FiMessageSquare className="text-blue-600" size={28} />
              Messagerie
            </h1>
            <p className="text-slate-500 mt-2">
              {chats.length === 0 ? 'Aucune conversation pour le moment.' : `${chats.length} conversation${chats.length > 1 ? 's' : ''}`}
            </p>
          </div>
          <div className="inline-flex items-center gap-2 rounded-full bg-slate-100 px-4 py-2 text-sm text-slate-600">
            <FiUsers className="text-slate-400" />
            {chats.filter((chat) => chat.isGroup).length} groupes
          </div>
        </div>
      </div>

      {chats.length === 0 ? (
        <div className="text-center py-16 bg-slate-50 rounded-[2rem] border border-dashed border-slate-300">
          <FiMessageSquare className="mx-auto text-slate-400 mb-4" size={52} />
          <h3 className="text-2xl font-semibold text-slate-900 mb-2">Aucune conversation</h3>
          <p className="text-slate-500 max-w-xl mx-auto">Toutes vos discussions apparaîtront ici. Cliquez sur une conversation pour ouvrir la messagerie.</p>
        </div>
      ) : (
        <div className="grid gap-4">
          {chats.map((chat) => {
            const recipientName = getRecipientName(chat);
            const unreadCount = chat.unreadCount || 0;
            return (
              <Link
                key={chat.id}
                to={`/chats/${chat.id}`}
                className="group block bg-white border border-slate-200 rounded-3xl p-4 hover:border-blue-300 hover:shadow-lg transition-all duration-200"
              >
                <div className="flex items-center gap-4">
                  <div
                    className="w-14 h-14 rounded-full flex items-center justify-center text-white font-bold text-lg flex-shrink-0"
                    style={{ backgroundColor: getAvatarColor(recipientName) }}
                  >
                    {recipientName.charAt(0).toUpperCase()}
                  </div>
                  <div className="min-w-0 flex-1">
                    <div className="flex items-center justify-between gap-4">
                      <h3 className="font-semibold text-slate-900 truncate">{recipientName}</h3>
                      {unreadCount > 0 && (
                        <span className="inline-flex items-center rounded-full bg-blue-100 text-blue-700 px-3 py-1 text-xs font-semibold">
                          {unreadCount} non lu{unreadCount > 1 ? 's' : ''}
                        </span>
                      )}
                    </div>
                    <p className="text-sm text-slate-500 mt-1 truncate">{getLastMessage(chat)}</p>
                  </div>
                </div>
                <div className="mt-4 flex items-center justify-between text-xs text-slate-400">
                  <span>{chat.isGroup ? `${getParticipants(chat).length} membres` : 'Conversation privée'}</span>
                  <span>{getLastMessageTime(chat)}</span>
                </div>
              </Link>
            );
          })}
        </div>
      )}
    </div>
  );
};

export default ChatList;
